solution:
Counter <- setRefClass("Counter",
  fields = list(count = "numeric"),
  methods = list(
    initialize = function(...) {
      count <<- 0
      callSuper(...)
    },
    add = function(n = 1) {
      count <<- count + n
      invisible(.self)
    },
    get = function() count
  )
)
